enum class CertificateChoices_kind {
    certificate,
    extendedCertificate,
    v1AttrCert,
    v2AttrCert,
    other,
    unknown
};

struct CertificateChoices {
    CertificateChoices_kind kind{};
    std::variant<::asn1kit::modern::PKIX1Explicit2009::Certificate, ExtendedCertificate, ::asn1kit::modern::AttributeCertificateVersion12009::AttributeCertificateV1, ::asn1kit::modern::PKIXAttributeCertificate2009::AttributeCertificate, OtherCertificateFormat> value{};
    std::optional<asn1kit::any> unknown{};

    static CertificateChoices from_certificate(::asn1kit::modern::PKIX1Explicit2009::Certificate v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::certificate;
        result.value.emplace<0>(std::move(v));
        return result;
    }

    static CertificateChoices from_extendedCertificate(ExtendedCertificate v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::extendedCertificate;
        result.value.emplace<1>(std::move(v));
        return result;
    }

    static CertificateChoices from_v1AttrCert(::asn1kit::modern::AttributeCertificateVersion12009::AttributeCertificateV1 v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::v1AttrCert;
        result.value.emplace<2>(std::move(v));
        return result;
    }

    // ASN.1 alias AttributeCertificateV2 ::= AttributeCertificate.
    static CertificateChoices from_v2AttrCert(::asn1kit::modern::PKIXAttributeCertificate2009::AttributeCertificate v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::v2AttrCert;
        result.value.emplace<3>(std::move(v));
        return result;
    }

    static CertificateChoices from_other(OtherCertificateFormat v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::other;
        result.value.emplace<4>(std::move(v));
        return result;
    }

    static CertificateChoices from_unknown(asn1kit::any v) {
        CertificateChoices result{};
        result.kind = CertificateChoices_kind::unknown;
        result.unknown = std::move(v);
        return result;
    }

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return (t.matches_ignore_constructed(asn1kit::tag::sequence) || t.matches_ignore_constructed(asn1kit::tag::context(0, true)) || t.matches_ignore_constructed(asn1kit::tag::context(1, true)) || t.matches_ignore_constructed(asn1kit::tag::context(2, true)) || t.matches_ignore_constructed(asn1kit::tag::context(3, true)));
    }

    static CertificateChoices decode(asn1kit::reader& r) {
        asn1kit::tag peeked;
        if (!r.try_peek_tag(peeked)) throw asn1kit::exception("Expected CHOICE alternative.");
        if (peeked.matches_ignore_constructed(asn1kit::tag::sequence)) {
            ::asn1kit::modern::PKIX1Explicit2009::Certificate alt{};
            alt = ::asn1kit::modern::PKIX1Explicit2009::Certificate::decode(r);
            return from_certificate(std::move(alt));
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(0, true))) {
            ExtendedCertificate alt{};
            alt = ExtendedCertificate::decode(r, asn1kit::tag::context(0, true));
            return from_extendedCertificate(std::move(alt));
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(1, true))) {
            ::asn1kit::modern::AttributeCertificateVersion12009::AttributeCertificateV1 alt{};
            alt = ::asn1kit::modern::AttributeCertificateVersion12009::AttributeCertificateV1::decode(r, asn1kit::tag::context(1, true));
            return from_v1AttrCert(std::move(alt));
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(2, true))) {
            ::asn1kit::modern::PKIXAttributeCertificate2009::AttributeCertificate alt{};
            alt = ::asn1kit::modern::PKIXAttributeCertificate2009::AttributeCertificate::decode(r, asn1kit::tag::context(2, true));
            return from_v2AttrCert(std::move(alt));
        } else if (peeked.matches_ignore_constructed(asn1kit::tag::context(3, true))) {
            OtherCertificateFormat alt{};
            alt = OtherCertificateFormat::decode(r, asn1kit::tag::context(3, true));
            return from_other(std::move(alt));
        } else {
            return from_unknown(r.read_any());
        }
    }

    static CertificateChoices decode(asn1kit::reader& r, const asn1kit::tag& t) {
        (void)t;
        return decode(r);
    }

    void encode(asn1kit::writer& w) const {
        switch (kind) {
        case CertificateChoices_kind::certificate:
            {
                const auto& alt = std::get<0>(value);
                alt.encode(w);
                break;
            }
        case CertificateChoices_kind::extendedCertificate:
            {
                const auto& alt = std::get<1>(value);
                alt.encode(w, asn1kit::tag::context(0, true));
                break;
            }
        case CertificateChoices_kind::v1AttrCert:
            {
                const auto& alt = std::get<2>(value);
                alt.encode(w, asn1kit::tag::context(1, true));
                break;
            }
        case CertificateChoices_kind::v2AttrCert:
            {
                const auto& alt = std::get<3>(value);
                alt.encode(w, asn1kit::tag::context(2, true));
                break;
            }
        case CertificateChoices_kind::other:
            {
                const auto& alt = std::get<4>(value);
                alt.encode(w, asn1kit::tag::context(3, true));
                break;
            }
        case CertificateChoices_kind::unknown:
            if (!unknown.has_value()) throw asn1kit::exception("Missing unknown CHOICE value.");
            w.write_any(*unknown);
            break;
        }
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t) const {
        (void)t;
        encode(w);
    }
};

struct OriginatorInfo {
    // ASN.1 alias CertificateSet ::= SET OF CertificateChoices.
    std::optional<std::vector<CertificateChoices>> certs{};
    // ASN.1 alias RevocationInfoChoices ::= SET OF RevocationInfoChoice.
    std::optional<std::vector<RevocationInfoChoice>> crls{};

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return t.matches_ignore_constructed(asn1kit::tag::sequence);
    }

    static OriginatorInfo decode(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::sequence) {
        OriginatorInfo value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            if (inner.next_is(asn1kit::tag::context(0, true))) {
                value.certs = inner.read_set_of<CertificateChoices>(asn1kit::tag::context(0, true));
            }
            if (inner.next_is(asn1kit::tag::context(1, true))) {
                value.crls = inner.read_set_of<RevocationInfoChoice>(asn1kit::tag::context(1, true));
            }
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = asn1kit::tag::sequence) const {
        auto scope = w.enter_sequence(t);
        if (this->certs.has_value()) {
            w.write_set_of(asn1kit::tag::context(0, true), (*this->certs));
        }
        if (this->crls.has_value()) {
            w.write_set_of(asn1kit::tag::context(1, true), (*this->crls));
        }
    }
};

template <typename Target>
struct AuthenticatedDataAuthAttributeSetOpenView;
template <typename Target>
struct AuthenticatedDataMessageAuthenticationCodeAlgorithmSetOpenView;
struct AuthenticatedData {
    std::int32_t version{};
    std::optional<OriginatorInfo> originatorInfo{};
    // ASN.1 alias RecipientInfos ::= SET OF RecipientInfo. ASN.1 SIZE (1..MAX). Not enforced by runtime.
    std::vector<RecipientInfo> recipientInfos{};
    // ASN.1 alias MessageAuthenticationCodeAlgorithm ::= AlgorithmIdentifier. ASN.1 object set MessageAuthenticationCodeAlgorithmSet (extensible). Membership not enforced by runtime.
    ::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier macAlgorithm{};
    // ASN.1 alias DigestAlgorithmIdentifier ::= AlgorithmIdentifier. ASN.1 object set DigestAlgorithmSet (extensible). Membership not enforced by runtime.
    std::optional<::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier> digestAlgorithm{};
    EncapsulatedContentInfo encapContentInfo{};
    // ASN.1 alias AuthAttributes ::= SET OF Attribute. ASN.1 SIZE (1..MAX). Not enforced by runtime.
    std::optional<std::vector<Attribute>> authAttrs{};
    // ASN.1 alias MessageAuthenticationCode ::= OCTET STRING.
    asn1kit::bytes mac{};
    // ASN.1 alias UnauthAttributes ::= SET OF Attribute. ASN.1 SIZE (1..MAX). Not enforced by runtime.
    std::optional<std::vector<Attribute>> unauthAttrs{};

    [[nodiscard]] AuthenticatedDataAuthAttributeSetOpenView<AuthenticatedData> auth_attribute_set() &;
    [[nodiscard]] AuthenticatedDataAuthAttributeSetOpenView<const AuthenticatedData> auth_attribute_set() const &;
    [[nodiscard]] AuthenticatedDataAuthAttributeSetOpenView<asn1kit::open_owned_target<AuthenticatedData>> auth_attribute_set() &&;
    AuthenticatedDataAuthAttributeSetOpenView<const AuthenticatedData> auth_attribute_set() const && = delete;

    [[nodiscard]] AuthenticatedDataMessageAuthenticationCodeAlgorithmSetOpenView<AuthenticatedData> message_authentication_code_algorithm_set() &;
    [[nodiscard]] AuthenticatedDataMessageAuthenticationCodeAlgorithmSetOpenView<const AuthenticatedData> message_authentication_code_algorithm_set() const &;
    [[nodiscard]] AuthenticatedDataMessageAuthenticationCodeAlgorithmSetOpenView<asn1kit::open_owned_target<AuthenticatedData>> message_authentication_code_algorithm_set() &&;
    AuthenticatedDataMessageAuthenticationCodeAlgorithmSetOpenView<const AuthenticatedData> message_authentication_code_algorithm_set() const && = delete;

    template <typename T>
    [[nodiscard]] std::optional<T> try_decode_mac_algorithm(
        const asn1kit::open_binding<asn1kit::open_context<"AlgorithmInformation-2009.pOPAlgs_parameters">, asn1kit::oid, T>& binding) const {
        return asn1kit::try_decode_unique((*this).macAlgorithm, binding);
    }

    template <typename T>
    [[nodiscard]] std::optional<std::vector<T>> try_decode_auth_attrs(
        const asn1kit::open_binding<asn1kit::open_context<"CryptographicMessageSyntax-2009.authAttributeSet">, asn1kit::oid, std::vector<T>>& binding) const {
        if (!(*this).authAttrs.has_value()) return std::nullopt;
        return asn1kit::try_decode_unique((*(*this).authAttrs), binding);
    }

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return t.matches_ignore_constructed(asn1kit::tag::sequence);
    }

    static AuthenticatedData decode(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::sequence) {
        AuthenticatedData value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            value.version = inner.read_int32(asn1kit::tag::integer);
            if (inner.next_is(asn1kit::tag::context(0, true))) {
                value.originatorInfo = OriginatorInfo::decode(inner, asn1kit::tag::context(0, true));
            }
            value.recipientInfos = inner.read_set_of<RecipientInfo>();
            value.macAlgorithm = ::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier::decode(inner);
            if (inner.next_is(asn1kit::tag::context(1, true))) {
                value.digestAlgorithm = ::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier::decode(inner, asn1kit::tag::context(1, true));
            }
            value.encapContentInfo = EncapsulatedContentInfo::decode(inner);
            if (inner.next_is(asn1kit::tag::context(2, true))) {
                value.authAttrs = inner.read_set_of<Attribute>(asn1kit::tag::context(2, true));
            }
            value.mac = inner.read_octet_string(asn1kit::tag::octet_string);
            if (inner.next_is(asn1kit::tag::context(3, true))) {
                value.unauthAttrs = inner.read_set_of<Attribute>(asn1kit::tag::context(3, true));
            }
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = asn1kit::tag::sequence) const {
        auto scope = w.enter_sequence(t);
        w.write_integer(asn1kit::tag::integer, this->version);
        if (this->originatorInfo.has_value()) {
            (*this->originatorInfo).encode(w, asn1kit::tag::context(0, true));
        }
        w.write_set_of(asn1kit::tag::set, this->recipientInfos);
        this->macAlgorithm.encode(w);
        if (this->digestAlgorithm.has_value()) {
            (*this->digestAlgorithm).encode(w, asn1kit::tag::context(1, true));
        }
        this->encapContentInfo.encode(w);
        if (this->authAttrs.has_value()) {
            w.write_set_of(asn1kit::tag::context(2, true), (*this->authAttrs));
        }
        w.write_octet_string(asn1kit::tag::octet_string, this->mac.span());
        if (this->unauthAttrs.has_value()) {
            w.write_set_of(asn1kit::tag::context(3, true), (*this->unauthAttrs));
        }
    }
};

struct EnvelopedData {
    std::int32_t version{};
    std::optional<OriginatorInfo> originatorInfo{};
    // ASN.1 alias RecipientInfos ::= SET OF RecipientInfo. ASN.1 SIZE (1..MAX). Not enforced by runtime.
    std::vector<RecipientInfo> recipientInfos{};
    EncryptedContentInfo encryptedContentInfo{};
    // ASN.1 alias Attributes ::= SET OF Attribute. ASN.1 SIZE (1..MAX). Not enforced by runtime. ASN.1 object set UnprotectedAttributes (extensible). Membership not enforced by runtime.
    std::optional<std::vector<Attribute>> unprotectedAttrs{};

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return t.matches_ignore_constructed(asn1kit::tag::sequence);
    }

    static EnvelopedData decode(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::sequence) {
        EnvelopedData value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            value.version = inner.read_int32(asn1kit::tag::integer);
            if (inner.next_is(asn1kit::tag::context(0, true))) {
                value.originatorInfo = OriginatorInfo::decode(inner, asn1kit::tag::context(0, true));
            }
            value.recipientInfos = inner.read_set_of<RecipientInfo>();
            value.encryptedContentInfo = EncryptedContentInfo::decode(inner);
            auto next_extension = 4;
            while (true) {
                asn1kit::tag extension_tag;
                if (!inner.try_peek_tag(extension_tag)) break;
                if (extension_tag.matches_ignore_constructed(asn1kit::tag::context(1, true))) {
                    if (next_extension > 4) throw asn1kit::exception("Duplicate or unordered extension component 'unprotectedAttrs'.");
                    value.unprotectedAttrs = inner.read_set_of<Attribute>(asn1kit::tag::context(1, true));
                    next_extension = 5;
                }
                else {
                    (void)inner.read_any();
                }
            }
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = asn1kit::tag::sequence) const {
        auto scope = w.enter_sequence(t);
        w.write_integer(asn1kit::tag::integer, this->version);
        if (this->originatorInfo.has_value()) {
            (*this->originatorInfo).encode(w, asn1kit::tag::context(0, true));
        }
        w.write_set_of(asn1kit::tag::set, this->recipientInfos);
        this->encryptedContentInfo.encode(w);
        if (this->unprotectedAttrs.has_value()) {
            w.write_set_of(asn1kit::tag::context(1, true), (*this->unprotectedAttrs));
        }
    }
};

struct SignedData {
    std::int32_t version{};
    std::vector<::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier> digestAlgorithms{};
    EncapsulatedContentInfo encapContentInfo{};
    // ASN.1 alias CertificateSet ::= SET OF CertificateChoices.
    std::optional<std::vector<CertificateChoices>> certificates{};
    // ASN.1 alias RevocationInfoChoices ::= SET OF RevocationInfoChoice.
    std::optional<std::vector<RevocationInfoChoice>> crls{};
    // ASN.1 alias SignerInfos ::= SET OF SignerInfo.
    std::vector<SignerInfo> signerInfos{};

    static constexpr bool match_tag(const asn1kit::tag& t) {
        return t.matches_ignore_constructed(asn1kit::tag::sequence);
    }

    static SignedData decode(asn1kit::reader& r, const asn1kit::tag& t = asn1kit::tag::sequence) {
        SignedData value{};
        r.with_sequence(t, [&](asn1kit::reader& inner) {
            value.version = inner.read_int32(asn1kit::tag::integer);
            value.digestAlgorithms = inner.read_set_of<::asn1kit::modern::AlgorithmInformation2009::AlgorithmIdentifier>();
            value.encapContentInfo = EncapsulatedContentInfo::decode(inner);
            if (inner.next_is(asn1kit::tag::context(0, true))) {
                value.certificates = inner.read_set_of<CertificateChoices>(asn1kit::tag::context(0, true));
            }
            if (inner.next_is(asn1kit::tag::context(1, true))) {
                value.crls = inner.read_set_of<RevocationInfoChoice>(asn1kit::tag::context(1, true));
            }
            value.signerInfos = inner.read_set_of<SignerInfo>();
        });
        return value;
    }

    void encode(asn1kit::writer& w, const asn1kit::tag& t = asn1kit::tag::sequence) const {
        auto scope = w.enter_sequence(t);
        w.write_integer(asn1kit::tag::integer, this->version);
        w.write_set_of(asn1kit::tag::set, this->digestAlgorithms);
        this->encapContentInfo.encode(w);
        if (this->certificates.has_value()) {
            w.write_set_of(asn1kit::tag::context(0, true), (*this->certificates));
        }
        if (this->crls.has_value()) {
            w.write_set_of(asn1kit::tag::context(1, true), (*this->crls));
        }
        w.write_set_of(asn1kit::tag::set, this->signerInfos);
    }
};

